INSERT INTO [dbo].[Articles] 
([Id], [CategoryId], [EventId], [Title], [Description], [CoverImageUrl], [PublishDate], [ExpiryDate], [IsPinned], [Status])
VALUES 

(1, 4,  NULL,  N'義起吃的故事：一張餐桌，連結世界與台灣', N'<p>2023 年，創辦人帶著滿行李箱的義式食譜與對料理的熱情返台，在台北巷弄裡開了首個店面。</p><p>三年過去，義起吃從一張餐桌延伸出多樣化，但不變的是那份對食材的尊重與對用餐體驗的堅持。每一位走進門的客人，都是我們繼續前行的動力。</p><p>謝謝你，讓一個義大利的夢想在台灣生根。</p>', NULL, '2025-08-15', NULL, 0, 1),                                                                                                                                                                                                                                               
(2, 6,  NULL,  N'榮獲《天下雜誌》評選：2025 年最具特色餐飲品牌', N'<p>義起吃很榮幸入選《天下雜誌》2025 年度「最具特色餐飲品牌」名單，與多家頂尖餐廳並列。</p><p>評選委員會特別肯定我們在本地食材結合義式工法上的創新，以及在服務體驗上對每一個細節的用心。</p><p>這份肯定是對團隊所有夥伴努力的最佳回饋，我們將持續精進，不辜負每一位顧客的信任。</p>', NULL, '2025-09-05', NULL, 0, 1),                                                                                                                                                                                                                            
(3, 3,  NULL,  N'秋季限定：南瓜奶油燉飯溫暖上市', N'<p>金黃的秋天來了，義起吃以當季產地直送南瓜為主角，推出秋季限定南瓜奶油燉飯。</p><p>主廚以低溫慢煮南瓜泥打底，搭配 Arborio 米粒與帕馬森起司，每一口都是秋天最溫柔的擁抱。</p><p>限量供應，每日下午兩點起開放預訂，售完為止。</p>', NULL, '2025-10-01', '2025-11-30', 0, 2),                                                                                                                                                                                                                                                                                                  
(4, 5,  NULL,  N'冬季新品：黑松露薄片披薩限量登場', N'<p>義起吃冬季新品正式亮相——黑松露薄片披薩，以空運進口新鮮黑松露現刨於出爐熱披薩之上，香氣在瞬間奔放而出。</p><p>薄脆的餅底搭配白醬、布拉塔起司，再疊上松露薄片，是冬季最奢華的味覺體驗。每日限量 20 份，敬請提前預訂。</p>', NULL, '2025-11-01', '2026-01-31', 0, 2),                                                                                                                                                                                                                     
(5,  4,  NULL,  N'關於義起吃：從拿坡里帶回的最初感動', N'<p>義起吃 EatTogether 的誕生源於創辦人旅居義大利三年的尋味之旅。我們致力於將地中海的陽光與熱情帶回台灣。</p><p>從拿坡里街頭的披薩香到托斯卡納的松露香氣，每一道料理都承載著真實的義式記憶。我們相信，食物不只是填飽肚子，更是一種文化的傳遞與情感的連結。</p><p>感謝每一位陪伴我們走過這段旅程的朋友，義起吃，因你而更有意義。</p>', NULL, '2025-11-20', NULL, 1, 1),
(6, 1,  1,    N'聖誕義式嘉年華活動預告：限定甜點與驚喜禮遇等你來', N'<p>最浪漫的節日即將到來！義起吃特別企劃「聖誕義式嘉年華」，為您打造一個充滿義大利風情的耶誕夜。</p><p>活動期間消費滿 1500 元，即可獲得聖誕限定草莓千層蛋糕一份，數量有限。店內也將佈置聖誕主題場景，歡迎帶著親愛的家人與朋友一同留下美好記憶。</p><p>活動期間：2025/12/01 – 2025/12/26，歡迎提早預約。</p>', NULL, '2025-12-01', '2025-12-26', 0, 2),                                                                                                                                                                                                                                                  
(7, 1,  1,    N'聖誕嘉年華圓滿收官，感謝每一位朋友',  N'<p>回顧 2025 年末的聖誕嘉年華，那份熱鬧與歡樂依然記憶猶新。感謝每一位參與活動的朋友，讓這場義式聖誕盛宴充滿了溫度與笑聲。</p><p>活動期間，我們共送出超過 800 份聖誕限定草莓千層蛋糕，見證了無數家庭與好友的美好時刻。期待下一個冬季的再次相聚，義起吃將帶著更多驚喜等待您的到來。</p>', NULL, '2025-12-27', '2026-01-31', 0, 2),                                                                                                                                                                                                                  
(8,  4,  NULL,  N'職人堅持：低溫發酵 48 小時的手作麵團', N'<p>在義起吃的廚房裡，時間是我們最重要的調味料。我們堅持使用義大利進口麵粉，並進行長達 48 小時的低溫熟成發酵。</p><p>這個過程讓麵團產生自然的氣孔結構，烘烤後外酥內軟、帶有淡淡的麥香與微妙的發酵香氣。每一口披薩餅皮，都是職人對品質最誠摯的承諾。</p>',  NULL, '2026-01-10', NULL, 0, 1),                                                                                                                                                                                                                        
(9, 2,  NULL,  N'2026 年春節營業公告', N'<p>感謝各位顧客長期以來的支持與愛護，以下公告 2026 年春節期間營業資訊。</p><p>除夕（1/28）：僅供應午間場，晚間提早打烊。大年初一至初三（1/29–1/31）：全日正常營業，歡迎闔家蒞臨。大年初四起恢復正常營業時間。</p><p>春節期間座位較為緊張，建議提前來電或線上預約，祝大家新年快樂！</p>', NULL, '2026-01-15', '2026-01-31', 0, 2),                                                                                                                                                                                                                                                                
(10, 1,  4,    N'農曆新年推薦：酥炸墨魚圈新鮮登場', N'<p>過年了，義起吃以義式熱情迎接農曆新春！主廚特別推薦人氣招牌——酥炸墨魚圈，外皮酥脆金黃、內裡鮮嫩彈牙，是餐桌上最受歡迎的開胃亮點。</p><p>農曆新年期間消費滿 1000 元，即可獲得主廚招待酥炸墨魚圈一份，為您的年節聚餐增添一份義式溫暖。活動期間：2026/01/20 – 2026/02/10。</p>', NULL, '2026-01-20', '2026-02-10', 0, 2),                                                                                                                                                                                                                                                        
(11, 1,  6,    N'情人節限定：巧克力塔與燭光晚餐的完美組合', N'<p>二月，是屬於愛的季節。義起吃為每一對戀人精心規劃情人節限定饗宴，讓愛在餐桌上更加閃耀。</p><p>活動期間消費滿 1314 元，即可獲得主廚手作巧克力熔岩蛋糕一份。店內同步提供情人節特別佈置，歡迎預約雙人燭光座位，為你們的約會留下難忘回憶。</p><p>活動期間：2026/02/10 – 2026/02/16，座位有限，請提早預約。</p>', NULL, '2026-02-10', '2026-02-16', 0, 2),                                                                                                                                                                                                                               
(12, 5,  NULL,  N'春季新菜單上線：清爽地中海風沙拉系列', N'<p>隨著氣溫漸暖，義起吃全新春季菜單正式上線！這次特別推出地中海風沙拉系列，以新鮮生菜、烤蔬菜、橄欖與費達起司為基底，搭配手工油醋醬，清爽不油膩。</p><p>主打三款：經典尼斯沙拉、烤紅椒費達起司沙拉、以及季節水果芝麻葉沙拉。單點或搭配主餐享有優惠，歡迎嘗鮮。</p>', NULL, '2026-02-15', NULL, 0, 1),                                                                                                                                                                                                                                                                            
(13,  5,  NULL,  N'新品上市：全家分享餐 699 元起澎湃登場', N'<p>聚餐時總是為了點餐而傷腦筋嗎？全新推出「全家分享餐」，專為 4-6 位好友與家人聚會量身打造。</p><p>每套包含主廚精選前菜拼盤、人氣主餐兩款、手工麵包籃以及當日甜點，699 元起即可輕鬆享用，讓每一次聚餐都變得簡單又豐盛。</p>', NULL, '2026-02-21', NULL, 0, 1),                                                                                                                                                                                                                                                 
(14,  2,  8,    N'平日午間快閃：暖心咖啡免費贈送', N'<p>忙碌的上班日也需要片刻的放鬆。義起吃推出平日午間快閃禮，週一至週五 11:30 至 14:00 間來店用餐滿 500 元，送卡布奇諾一杯。</p><p>讓午後的陽光配上香醇的咖啡香，為您的下午充好電。活動期間：2026/03/01 – 2026/03/31，數量有限，先到先得。</p>', NULL, '2026-02-25', '2026-03-31', 0, 1),                                                                                                                                                                                                                                                                                                                     
(15,  1,  10,   N'學生專屬：憑學生證提拉米蘇免費請你吃', N'<p>期末考週辛苦了！義起吃為廣大學子加油打氣，特別推出「學生小確幸」活動。</p><p>只要您是具備有效學生證的在校生，平日來店單筆消費滿 350 元，我們就免費招待主廚手工製作的經典提拉米蘇一份。濃郁的馬斯卡彭起司搭配手指餅乾，讓每一口都是放鬆與享受。</p><p>活動期間：2026/03/16 – 2026/04/30，每位同學每次消費限用乙次。</p>', NULL, '2026-03-01', '2026-04-30', 0, 1),                                                                                                            
(16,  3,  9,    N'初夏海鮮祭：鮮美鮭魚排', N'<p>隨著天氣逐漸轉暖，大海的味道愈發誘人。義起吃 EatTogether 推出「初夏海鮮祭」，主廚嚴選優質鮭魚排，以檸檬奶油香煎提味。</p><p>每一片鮭魚排都是海洋的精華，搭配自製青醬義大利麵，鮮甜與濃郁在口中完美交融。消費滿 1800 元即可獲贈香煎鮭魚排一份，活動期間：2026/03/10 – 2026/03/17。</p>', NULL, '2026-03-08', '2026-03-17', 0, 1),
(17, 6,  NULL,  N'媒體報導：《食尚指南》評選全台必吃餐廳', N'<p>非常榮幸能獲得知名媒體《食尚指南》的專業肯定！在最新的年度餐廳評比中，義起吃被評選為「全台年度必吃義式餐廳」。</p><p>評審特別讚揚我們對食材品質的堅持，以及將義式飲食文化在地化的用心。這份殊榮屬於每一位支持義起吃的朋友，謝謝您的陪伴，讓我們繼續一起享受美食。</p>', NULL, '2026-03-15', NULL, 0, 1),
(18, 2,  11,   N'義起吃週年慶開跑：感謝三年來每一位老朋友', N'<p>時光飛逝，義起吃迎來第三個年頭！為感謝每一位陪伴我們成長的顧客，特別舉辦週年慶回饋活動。</p><p>活動期間（2026/03/18 – 2026/04/10）消費滿 1200 元，即享現折 150 元優惠。同時開放週年限定套餐預約，由主廚親自設計三道式料理，以義式傳統技法致敬三年的美好。</p><p>感謝有你，讓義起吃的每一天都更有意義。</p>', NULL, '2026-03-18', '2026-04-10', 1, 1),                                                                                                                                                                                                                                    
(19, 4,  NULL,  N'走進義起吃的廚房：食材從產地到餐桌的旅程', N'<p>您知道義起吃的橄欖油來自義大利普利亞區的百年橄欖樹嗎？每一瓶都是莊園當季初榨，酸度低、果香濃，是料理的靈魂所在。</p><p>我們相信好的食材不需要過多修飾，只需要對的烹調方式，就能讓食材本身的風味在餐盤上閃耀。從選材、運輸到料理，每一個環節都是義起吃對品質的承諾。</p>', NULL, '2026-04-01', NULL, 0, 1),                                                                                                                                                                                                                                                             
(20,  3,  13,   N'季節限定：春末松露慶典盛大展開', N'<p>春天的尾聲，我們將餐盤上的黑鑽石呈現給您。義起吃「春末松露慶典」正式揭幕，主廚特別選用進口優質黑松露，打造獨家松露起司薯條。</p><p>酥脆的薯條搭配瑞可塔起司與現刨松露，每一口都是春末最奢華的味蕾體驗。活動期間：2026/04/15 – 2026/05/15，消費滿 1200 元即可獲贈，數量有限。</p>', NULL, '2026-04-15', '2026-05-15', 0, 1),                                                                                                                                                                                                                                                                    
(21, 1,  15,   N'五一連假微放鬆：滿 800 立折 80，好好吃一頓',  N'<p>難得的五一連假，什麼都不用想，就是好好吃一頓！義起吃特別推出五一連假優惠，活動期間（2026/05/01 – 2026/05/04）全單消費滿 800 元，即享現折 80 元。</p><p>不論是家人聚餐、朋友小聚還是一個人的悠閒午后，義起吃都準備好迎接你的到來。歡迎線上提前預約，假日座位有限。</p>', NULL, '2026-05-01', '2026-05-04', 0, 1),
(22,  1,  14,   N'五月寵愛母親節，全桌 85 折優惠公告',　N'<p>溫馨五月將至，義起吃 EatTogether 邀請您與最重要的女性長輩一同共度美味時光。</p><p>我們特別推出寵愛母親節專案，凡於五月份帶著媽媽來店用餐，全桌消費滿 2000 元即可享有 85 折的超值優惠。無論是週末家庭聚會，還是平日的溫馨小聚，都希望在這個特別的季節，讓媽媽感受到滿滿的愛與美食的幸福。</p><p>活動期間：2026/05/01 – 2026/05/11，敬請把握！</p>', NULL, '2026-05-01', '2026-05-31', 1, 1),                                                                                                                                                                                                                                                   
(23,  2,  NULL,  N'義起吃 5/20 員工旅遊暫停營業一日', N'<p>親愛的顧客您好，為了感謝全體員工一年來的辛勞並提升服務團隊的凝聚力，義起吃 EatTogether 全台分店將於 2026 年 5 月 20 日暫停營業一日。</p><p>造成您的不便，我們深感抱歉，並將於 5 月 21 日恢復正常營業。歡迎您屆時再度蒞臨，我們期待以更好的狀態與服務迎接每一位貴客。</p>', NULL, '2026-05-10', '2026-05-21', 0, 0),                                                                                                                                                                                                                                                                                                   
(24, 5,  NULL,  N'週末限定：威尼斯墨魚義大利麵驚豔登場', N'<p>這個週末，來點不一樣的深海色彩吧！義起吃推出週末限定威尼斯墨魚義大利麵，採用當日現捕透抽搭配黑金墨魚醬汁，色澤深邃、鮮味濃郁。</p><p>搭配手工細麵與蒜香白酒提味，每一口都是海洋的呼喚。僅限週六、週日供應，數量有限，建議提早預約。</p>', NULL, '2026-05-20', NULL, 0, 0);                                                      



SET IDENTITY_INSERT [dbo].[Articles] OFF;
GO